#include "harness.hpp"
#include "loghist.hpp"

using namespace loghist;

int main() {
    h_init();
    Histogram h(2, 1000);
    CHECK_EQ(Histogram::bucket_index_of(2, 5), 5u);
    CHECK_EQ(Histogram::bucket_index_of(2, 9), 8u);
    h.record(3);
    h.record(10, 2);
    CHECK_EQ(h.total(), 3u);
    CHECK_EQ(h.percentile(1000), 11u);
    return h_report();
}

