    for (size_t i = 0; i < counts_.size(); i++) {
        if (counts_[i] > 0) return bucket_low(i);
    }
    return 0;
}

uint64_t Histogram::max_recorded() const {
    for (size_t i = counts_.size(); i > 0; i--) {
        if (counts_[i - 1] > 0) {
            uint64_t hi = bucket_high(i - 1);
            return hi > max_ ? max_ : hi;
        }
    }
    return 0;
}

