        std::snprintf(buf, sizeof buf, "%.10g", static_cast<double>(v));
        return buf;
    } else if constexpr (std::is_arithmetic_v<T>) {
        return std::to_string(v);
    } else if constexpr (h_is_seq<T>::value) {
        std::string s = "[";
        bool first = true;
        for (const auto &x : v) {
            if (!first) s += ", ";
            first = false;
            s += h_show(x);
        }
        return s + "]";
    } else {
        return "<value>";
    }
}

